(function(){function initialize(){document.querySelectorAll('nav .nav-inner').forEach(function(row){if(row.dataset.rxNavReady==='true')return;row.dataset.rxNavReady='true';var toggle=row.querySelector('.rx-mobile-nav-toggle');if(toggle){toggle.addEventListener('click',function(){var open=row.classList.toggle('rx-mobile-open');toggle.setAttribute('aria-expanded',String(open));});}row.querySelectorAll('.nav-dd').forEach(function(drop){var btn=drop.querySelector('.nav-dd-btn');if(!btn)return;btn.addEventListener('click',function(e){e.stopPropagation();var open=!drop.classList.contains('open');row.querySelectorAll('.nav-dd').forEach(function(other){other.classList.remove('open');var b=other.querySelector('.nav-dd-btn');if(b)b.setAttribute('aria-expanded','false');});drop.classList.toggle('open',open);btn.setAttribute('aria-expanded',String(open));});});});document.addEventListener('click',function(e){document.querySelectorAll('nav .nav-dd.open').forEach(function(drop){if(!drop.contains(e.target)){drop.classList.remove('open');var b=drop.querySelector('.nav-dd-btn');if(b)b.setAttribute('aria-expanded','false');}});});document.addEventListener('keydown',function(e){if(e.key==='Escape')document.querySelectorAll('nav .nav-dd.open').forEach(function(drop){drop.classList.remove('open');var b=drop.querySelector('.nav-dd-btn');if(b)b.setAttribute('aria-expanded','false');});});document.querySelectorAll('#installCmd').forEach(function(btn){if(btn.dataset.rxReady)return;btn.dataset.rxReady='1';btn.addEventListener('click',function(){var command='pip install remyxai';if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(command).catch(function(){});}else{var t=document.createElement('textarea');t.value=command;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();}var label=btn.querySelector('#copyLabel');if(label)label.textContent='copied';});});document.querySelectorAll('#eventVideo').forEach(function(node){if(node.dataset.rxReady)return;node.dataset.rxReady='1';function play(){var iframe=document.createElement('iframe');iframe.src='https://www.youtube-nocookie.com/embed/tpJDMEfyXJU?autoplay=1';iframe.title='Experiment 2025 event video';iframe.allow='accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture;web-share';iframe.allowFullscreen=true;iframe.style.cssText='display:block;width:100%;height:100%;min-height:280px;border:0';node.innerHTML='';node.appendChild(iframe);node.removeAttribute('role');node.removeAttribute('tabindex');}node.addEventListener('click',play);node.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();play();}});});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initialize);else initialize();})();(function(){const root=document.getElementById('rxh-flow');if(!root||root.dataset.cameraReady==='true')return;root.dataset.cameraReady='true';const tabs=Array.from(root.querySelectorAll('.rxh-map-control'));const captions=Array.from(root.querySelectorAll('[data-caption]'));const svgDesktop=root.querySelector('svg.rxh-map-desktop');const svgMobile=root.querySelector('svg.rxh-map-mobile');const svgList=[svgDesktop,svgMobile].filter(Boolean);const cameras={desktop:[[42,53,320,130],[43,43,420,150],[32,10,679,209]],mobile:[[8,49,225,138],[8,38,304,159],[0,10,400,204]]};let phase=0;let timer=null;let frame=null;let reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;function ease(t){return 1-Math.pow(1-t,3);}function box(svg){return svg.getAttribute('viewBox').trim().split(/[\s,]+/).map(Number);}function setBox(svg,vals){svg.setAttribute('viewBox',vals.map(n=>(Math.round(n*100)/100)).join(' '));}function cameraFor(svg,n){return cameras[svg===svgMobile?'mobile':'desktop'][n];}function moveCamera(n,immediate){if(frame!==null){cancelAnimationFrame(frame);frame=null;}const begin=svgList.map(box);const target=svgList.map(svg=>cameraFor(svg,n));if(reduced||immediate){svgList.forEach((svg,i)=>setBox(svg,target[i]));return;}const started=performance.now();const duration=900;function animate(now){const t=ease(Math.min(1,(now-started)/duration));svgList.forEach((svg,i)=>setBox(svg,begin[i].map((v,j)=>v+(target[i][j]-v)*t)));if(t<1){frame=requestAnimationFrame(animate);}else{frame=null;}}frame=requestAnimationFrame(animate);}function show(n,immediate){phase=n;root.dataset.phase=String(n);tabs.forEach((btn,i)=>{const active=i===n;btn.classList.toggle('is-active',active);btn.setAttribute('aria-pressed',active?'true':'false');});captions.forEach((el,i)=>el.classList.toggle('is-active',i===n));moveCamera(n,immediate);}function stop(){if(timer!==null){clearInterval(timer);timer=null;}}function play(){stop();if(reduced||document.hidden)return;timer=setInterval(()=>show((phase+1)%3,false),4800);}tabs.forEach((btn,i)=>btn.addEventListener('click',()=>{show(i,false);play();}));root.addEventListener('mouseenter',stop);root.addEventListener('mouseleave',play);root.addEventListener('focusin',stop);root.addEventListener('focusout',play);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else play();});show(0,true);play();})();(function(){function initializeReveals(){var elements=Array.from(document.querySelectorAll('.reveal'));if(!elements.length)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver'in window)){elements.forEach(function(el){el.classList.add('show');});return;}var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('show');observer.unobserve(entry.target);}});},{threshold:.08});elements.forEach(function(el){if(!el.classList.contains('show'))observer.observe(el);});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initializeReveals,{once:true});else initializeReveals();})();
